-- preflight for 27-30 (SELECT only): target sets - drafts, quant-evidence count, attempts; already-imported quant gids
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_QUANT=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

select s.name, s.version_no, s.status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.skill_code = 'command_of_evidence_quant') as quant_items,
  (select count(*) from mock_exam_sets d where d.set_group_id = s.set_group_id and d.status = 'draft' and d.archived_at is null) as existing_drafts,
  (select count(*) from mock_exam_attempts a where a.exam_set_id = s.id) as attempts
from mock_exam_sets s where s.name = any (array['SAT Practice Test 6','SAT Practice Test 10','SAT Practice Test 11','SAT Practice Test 12','SAT Practice Test 13','SAT Practice Test 16','SAT Practice Test 17','SAT Practice Test 18','SAT Practice Test 19','SAT Practice Test 20','SAT Practice Test 22','SAT Practice Test 23','SAT Practice Test 24','SAT Practice Test 25','SAT Practice Test 27','SAT Practice Test 30']) and s.status = 'published' and s.archived_at is null order by length(s.name), s.name;
select count(*) as already_imported_quant_gids from problem_versions where quality->'mockExamGeneration'->>'gid' = any (array['quant-pair-compare-20261027','quant-ratio-vs-baseline-20261090','quant-target-met-20261097','quant-max-change-20261104','quant-max-step-20261111','quant-pair-compare-20261118','quant-ratio-vs-baseline-20261293','quant-target-met-20261300','quant-max-change-20261307','quant-max-step-20261314','quant-pair-compare-20261321','quant-ratio-vs-baseline-20261356','quant-target-met-20261363','quant-max-change-20261370','quant-max-step-20261377','quant-pair-compare-20261384','quant-ratio-vs-baseline-20261447','quant-target-met-20261454','quant-max-change-20261461','quant-max-step-20261468','quant-pair-compare-20261475','quant-ratio-vs-baseline-20261622','quant-target-met-20261636','quant-max-change-20261678','quant-max-step-20261685','quant-pair-compare-20261692','quant-ratio-vs-baseline-20261727','quant-target-met-20261741','quant-max-change-20261755','quant-max-step-20261762','quant-pair-compare-20261769','quant-ratio-vs-baseline-20261874','quant-target-met-20261888','quant-max-change-20261923','quant-max-step-20261930','quant-pair-compare-20261937']);
